// Generates extension/keyword_intent.js from engine/vendor/providers/keyword.ts (types erased, logic and line numbers kept).
// The extension is loaded unbuilt in server mode, so the generated file is kept next to the sources ; a unit test checks it has not drifted.
// Usage : node extension/tools/gen_keyword.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = resolve(HERE, '..', '..', 'engine', 'vendor', 'providers', 'keyword.ts');
const OUT = join(HERE, '..', 'keyword_intent.js');
export const HEADER = '// GENERATED by tools/gen_keyword.mjs from engine/vendor/providers/keyword.ts : do not edit.\n';
export function generate() { return HEADER + stripTypeScriptTypes(readFileSync(SRC, 'utf8'), { mode: 'strip' }); }

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const js = generate();
  if (process.argv.includes('--check')) { if (readFileSync(OUT, 'utf8') !== js) { console.error('keyword_intent.js is stale'); process.exit(1); } console.log('keyword_intent.js up to date'); }
  else { writeFileSync(OUT, js); console.log('written ' + OUT); }
}
